import * as THREE from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasW = 512;
  const atlasH = 320;

  const aspect = rect.w / rect.h;
  const height = 1.4;
  const width = height * aspect;

  const geometry = new THREE.PlaneGeometry(width, height);

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/floating-accent.png');
  map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = THREE.ClampToEdgeWrapping;
  map.wrapT = THREE.ClampToEdgeWrapping;

  const uOffset = rect.x / atlasW;
  const vOffset = 1.0 - (rect.y + rect.h) / atlasH;
  const uScale = rect.w / atlasW;
  const vScale = rect.h / atlasH;

  const uvNode = uv().mul(vec2(uScale, vScale)).add(vec2(uOffset, vOffset));

  const material = new THREE.MeshBasicNodeMaterial();
  material.map = texture(map, uvNode);
  material.transparent = true;
  material.depthWrite = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'features-card-2-accent';

  const node = new THREE.Object3D();
  node.name = 'hub-features-card-2';
  node.add(mesh);

  node.position.set(0, -0.3, 0);
  node.rotation.set(0, 0, 0);
  node.scale.set(1, 1, 1);

  const camera = ctx.camera;
  node.userData.handlers = {
    update: () => {
      if (camera) {
        mesh.quaternion.copy(camera.quaternion);
      }
    }
  };

  node.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return node;
}
